import{_ as d,o as a,c as e,a2 as r}from"./chunks/framework.Bg-Zxr5O.js";const D=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/Functions.md","filePath":"manual-zh/Functions.md","lastUpdated":1785684581000}'),A={name:"manual-zh/Functions.md"};function n(N,t,o,S,E,s){return a(),e("div",null,[...t[0]||(t[0]=[r('<h3 id="_7-7-函数" tabindex="-1">7.7 函数 <a class="header-anchor" href="#_7-7-函数" aria-label="Permalink to &quot;7.7 函数&quot;">​</a></h3><p>PSPP 函数提供使用简单运算符无法实现的高级数学能力。函数有共同的语法：每个函数由函数名、左括号、一个或多个参数和右括号组成。</p><p>函数名不是保留字。它们的名称只有在后跟左括号时才被特殊处理，因此 ‘EXP(10)’ 指常数 <em>e</em> 的 10 次方，但 ‘EXP’ 本身指名为 <code>EXP</code> 的变量的值。</p><p>以下各节详细描述每个函数。</p><table tabindex="0"><thead><tr><th>• 数学</th><th></th><th>EXP LG10 LN LNGAMMA SQRT</th></tr></thead><tbody><tr><td>• 杂项数学</td><td></td><td>ABS MOD MOD10 RND TRUNC</td></tr><tr><td>• 三角函数</td><td></td><td>ACOS ARCOS ARSIN ARTAN ASIN ATAN COS SIN TAN</td></tr><tr><td>• 缺失值函数</td><td></td><td>MISSING NMISS NVALID SYSMIS VALUE</td></tr><tr><td>• 集合成员关系</td><td></td><td>ANY RANGE</td></tr><tr><td>• 统计函数</td><td></td><td>CFVAR MAX MEAN MEDIAN MIN SD SUM VARIANCE</td></tr><tr><td>• 字符串函数</td><td></td><td>CONCAT INDEX LENGTH LOWER LPAD LTRIM NUMBER REPLACE RINDEX RPAD RTRIM STRING STRUNC SUBSTR UPCASE</td></tr><tr><td>• 时间与日期</td><td></td><td>CTIME.xxx DATE.xxx TIME.xxx XDATE.xxx DATEDIFF DATESUM</td></tr><tr><td>• 杂项函数</td><td></td><td>LAG YRMODA VALUELABEL</td></tr><tr><td>• 统计分布函数</td><td></td><td>PDF CDF SIG IDF RV NPDF NCDF</td></tr></tbody></table>',5)])])}const I=d(A,[["render",n]]);export{D as __pageData,I as default};
